    "appearance": "Lợn rừng đen, hàm dưới là rễ cây và lưng đội bia mộ trẻ con. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: xám tàn, lục rêu lạnh và cam tro; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ vừa 1–2,5 m.",
    "temperament": "Ủi đất quanh những mộ bị quên, ăn củ mọc trong tro hương. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở mái miếu cháy, thỉnh thoảng di chuyển tới bãi mộ không bia của miền tây Vạn Tro. Nó hoạt động rõ nhất chạng vạng và những giờ rừng lặng gió. Dấu vết thường đi kèm mùi gỗ ướt xen khói nguội. Lẻ hoặc theo cặp; đôi khi tụ đàn đúng mùa. Cơ chế tái tạo quần thể gợi ý: kết tụ từ nghi thức hoặc lời hứa bỏ quên; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Đào đường hầm nhả dây rễ trói chân kẻ đạp mộ. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: phá đội hình.",
    "weakness": "Không thể đi qua ranh muối còn nguyên. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: nanh rễ hóa thạch. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Bản đồ sinh cảnh thay đổi theo mùa. Khi nguồn thức ăn dịch chuyển, loài cũng rời điểm xuất hiện cố định, tránh cảm giác quái vật đứng canh một chỗ vô cớ.",
    "questHook": "Đàn lợn đang kéo cả nghĩa trang về phía khu dân cư. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
