    "region": "RỪNG LẶNG TRO",
    "appearance": "Rết dài ba mét, từng đốt treo mặt nạ người đan bằng lá mục. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: xám tàn, lục rêu lạnh và cam tro; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ nhỏ 0,3–1,2 m.",
    "temperament": "Ăn rêu trên các nhà hát bị cháy; gom mặt nạ từ vật hiến tế. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở rừng dâu hoang, thỉnh thoảng di chuyển tới khe rễ cổ của miền tây Vạn Tro. Nó hoạt động rõ nhất chạng vạng và những giờ rừng lặng gió. Dấu vết thường đi kèm mùi gỗ ướt xen khói nguội. Từ một tổ nhỏ đến đàn tùy nguồn thức ăn. Cơ chế tái tạo quần thể gợi ý: tách mầm từ cơ quan mẹ; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Mỗi mặt nạ phát một giọng khác khiến nhóm người chơi nhầm mục tiêu. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: chống chịu.",
    "weakness": "Mặt nạ cuối đuôi chỉ chịu nổi tiếng cười. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: giáp lá có vân mặt. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Những người sống lâu trong vùng coi dấu hiệu này là một lời nhắc về Trăng Vỡ, không phải bằng chứng rằng mọi cá thể đều độc ác.",
    "questHook": "Một đoàn diễn viên mất giọng sau buổi diễn ở sân rừng. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
