    "appearance": "Nai thân mảnh, sừng ghép thành khung cửa đang mở, lông đầy ổ khóa nhỏ. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: xám tàn, lục rêu lạnh và cam tro; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ nhỏ 0,3–1,2 m.",
    "temperament": "Gặm địa y trên cổng bỏ hoang; chỉ đến gần người đang muốn trốn chạy. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở mái miếu cháy, thỉnh thoảng di chuyển tới bãi mộ không bia của miền tây Vạn Tro. Nó hoạt động rõ nhất chạng vạng và những giờ rừng lặng gió. Dấu vết thường đi kèm mùi gỗ ướt xen khói nguội. Lẻ hoặc theo cặp; đôi khi tụ đàn đúng mùa. Cơ chế tái tạo quần thể gợi ý: sinh con non được cả đàn bảo vệ; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Cho phép bước tắt giữa hai thân cây nhưng đóng cửa khi con mồi đi nửa chừng. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: đổi vị trí.",
    "weakness": "Ổ khóa giữa trán mở được bằng chìa làm từ gỗ sống. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: chìa sừng thô. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Bản đồ sinh cảnh thay đổi theo mùa. Khi nguồn thức ăn dịch chuyển, loài cũng rời điểm xuất hiện cố định, tránh cảm giác quái vật đứng canh một chỗ vô cớ.",
    "questHook": "Thương nhân mất tích sau khi chọn lối tắt không có trên bản đồ. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
