    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: da khắc tự. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Người dân thường cố dùng hàng rào, nghi thức hoặc trao đổi để tránh xung đột thay vì tổ chức săn diệt triệt để.",
