    "appearance": "Chim hạc cổ dài, mỏ kim cong và cánh phủ dải hoàng hôn cam tím. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: xám tàn, lục rêu lạnh và cam tro; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: lớn; cần không gian để tạo lối đánh riêng.",
