    "habitat": "Ghi nhận dày nhất ở khe rễ cổ, thỉnh thoảng di chuyển tới rừng dâu hoang của miền tây Vạn Tro. Nó hoạt động rõ nhất lúc bình minh, trừ khi chạng vạng và những giờ rừng lặng gió. Dấu vết thường đi kèm mùi gỗ ướt xen khói nguội. Hiếm, thường chỉ có một cá thể trong một tiểu vùng. Cơ chế tái tạo quần thể gợi ý: đẻ trứng trong ổ kín; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Khâu hai khoảng tối lại thành vách chắn xuyên sáng. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: tinh anh vùng.",
    "weakness": "Không khâu được bóng trên nền phủ sương bạc. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: kim mỏ ráng chiều. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Người dân thường cố dùng hàng rào, nghi thức hoặc trao đổi để tránh xung đột thay vì tổ chức săn diệt triệt để.",
    "questHook": "Bình minh đến chậm vì một bầy chim giấu ánh sáng của cả thung lũng. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
