    "temperament": "Lượn dưới tàu chở tù nhân, hút sắt từ xích rơi xuống. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở rạn chuông chìm, thỉnh thoảng di chuyển tới cửa hang triều của vành biển phía nam. Nó hoạt động rõ nhất nước triều đổi hướng hoặc đêm có sương mặn. Dấu vết thường đi kèm tiếng kim loại vang từ mặt nước. Lẻ hoặc theo cặp; đôi khi tụ đàn đúng mùa. Cơ chế tái tạo quần thể gợi ý: tách mầm từ cơ quan mẹ; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Đóng ấn dưới chân gây cấm dùng một nhóm kỹ năng tạm thời. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: đổi vị trí.",
    "weakness": "Ấn mất hiệu lực khi rửa bằng nước giếng đất liền. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: mực triện máu. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Bản đồ sinh cảnh thay đổi theo mùa. Khi nguồn thức ăn dịch chuyển, loài cũng rời điểm xuất hiện cố định, tránh cảm giác quái vật đứng canh một chỗ vô cớ.",
    "questHook": "Một viên cai ngục bí mật nuôi cá đuối để khóa phép tù nhân. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
