    "appearance": "Bộ xương đứng được nhờ rêu kết thành cơ, đầu là chậu đất mẻ. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: lục đầm, đen bùn và ánh lân tím; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ khổng lồ trên 6 m.",
    "temperament": "Lặng lẽ chăm gò mộ, bón rêu bằng lá mục và xua thú giẫm cây. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
