    "region": "HẠ TẦNG VỈA VỌNG",
    "appearance": "Nhện đá tám chân, bụng nở như khuôn đồng và răng cửa thành chày. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: than đen, lục tinh thể và đồng gỉ; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ nhỏ 0,3–1,2 m.",
    "temperament": "Chỉ săn ở lò đúc chuông bỏ hoang; ăn bọ ký sinh trên đồng. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở trục mỏ sâu, thỉnh thoảng di chuyển tới nhà máy cũ của bên dưới cả vùng trung nguyên. Nó hoạt động rõ nhất khi máy mỏ gõ hoặc dòng mạch dưới đất thay đổi. Dấu vết thường đi kèm nhịp gõ vọng không trùng nhịp tim. Từ một tổ nhỏ đến đàn tùy nguồn thức ăn. Cơ chế tái tạo quần thể gợi ý: tách mầm từ cơ quan mẹ; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Đúc một tiếng chuông vô hình chặn đường tiến của mục tiêu. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: chống chịu.",
    "weakness": "Khuôn nứt khi bị đánh bằng vật không làm từ kim loại. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: khuôn đồng rỗng. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Những người sống lâu trong vùng coi dấu hiệu này là một lời nhắc về Trăng Vỡ, không phải bằng chứng rằng mọi cá thể đều độc ác.",
    "questHook": "Người thợ đúc nghe tiếng chuông chưa từng được làm. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
