    "temperament": "Đẻ trứng cạnh hầm xương hóa thạch và ăn nấm từ bia mộ. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở nhà máy cũ, thỉnh thoảng di chuyển tới trục mỏ sâu của bên dưới cả vùng trung nguyên. Nó hoạt động rõ nhất khi máy mỏ gõ hoặc dòng mạch dưới đất thay đổi. Dấu vết thường đi kèm nhịp gõ vọng không trùng nhịp tim. Từ một tổ nhỏ đến đàn tùy nguồn thức ăn. Cơ chế tái tạo quần thể gợi ý: tách mầm từ cơ quan mẹ; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Gọi ra một bóng chưa định hình đỡ đòn trong thời gian ngắn. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: áp lực thời gian.",
    "weakness": "Bóng tan khi tên trên đá bị đảo chữ. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: viên bia non. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Người dân thường cố dùng hàng rào, nghi thức hoặc trao đổi để tránh xung đột thay vì tổ chức săn diệt triệt để.",
    "questHook": "Một trẻ sơ sinh được tiên đoán chết trước khi sinh. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
