    "temperament": "Lang thang nơi thợ mỏ bị chôn, gõ tín hiệu cứu hộ lặp mãi. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
