    "region": "BẠCH NGUYÊN VÔ NHẬT",
    "appearance": "Cáo đen có lớp tuyết bám da không bao giờ tan, mắt vàng sẫm. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: trắng xương, lam băng và tím cực quang; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ vừa 1–2,5 m.",
    "temperament": "Bắt chuột dưới tuyết, lén theo đoàn lữ hành để ăn thức ăn bỏ. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở hồ nứt, thỉnh thoảng di chuyển tới trạm cứu hộ bỏ của cực bắc. Nó hoạt động rõ nhất trong đêm dài hoặc khi cực quang dạt thấp. Dấu vết thường đi kèm tiếng nứt băng vọng trong không khí yên. Lẻ hoặc theo cặp; đôi khi tụ đàn đúng mùa. Cơ chế tái tạo quần thể gợi ý: kết tụ từ nghi thức hoặc lời hứa bỏ quên; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Chui qua lớp tuyết bất kỳ để đổi vị trí ở khoảng gần. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: canh lãnh thổ.",
    "weakness": "Không chui qua băng đặc trong suốt. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: lớp tuyết bất tan. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Những người sống lâu trong vùng coi dấu hiệu này là một lời nhắc về Trăng Vỡ, không phải bằng chứng rằng mọi cá thể đều độc ác.",
    "questHook": "Đường đi bí mật được phát hiện nhờ dấu cáo biến mất. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
