    "region": "VÀNH ĐAI MIẾU CÂM",
    "appearance": "Tượng gỗ hình người, ba mặt xoay quanh cổ nhưng chỉ một có mắt. Silhouette cần nhấn vào bộ phận biến dạng chính để người chơi nhận ra từ khoảng cách xa. Gợi ý mỹ thuật: đỏ chu sa, vàng hương và xám gỗ thờ; bề mặt kể chuyện qua các dấu mòn, vết nứt và chất liệu có thể nhìn thấy khi sinh vật tiến vào vùng sáng. Kích cỡ mục tiêu: cỡ khổng lồ trên 6 m.",
    "temperament": "Đi quanh những bậc thờ, thay mặt để canh ba hướng. Ngoài lúc bị đe dọa, hành vi của nó xoay quanh kiếm ăn, bảo vệ nơi trú hoặc phản ứng với con người; không nên cho tất cả cá thể tấn công ngay khi nhìn thấy. Khi gặp âm thanh lạ, nó thăm dò trước rồi mới áp sát hoặc rút lui tùy lợi thế địa hình.",
    "habitat": "Ghi nhận dày nhất ở sân miếu lạnh, thỉnh thoảng di chuyển tới giếng khấn im của quần thể miếu bao quanh kinh đô cũ. Nó hoạt động rõ nhất lúc bình minh, trừ khi giờ dâng lễ hoặc khi nghi thức bị làm sai. Dấu vết thường đi kèm mùi hương không có nguồn cháy. Hiếm; xuất hiện khi đủ điều kiện nghi thức. Cơ chế tái tạo quần thể gợi ý: kết tụ từ nghi thức hoặc lời hứa bỏ quên; cần đối chiếu với tuyến nhiệm vụ địa phương trước khi cố định lore.",
    "tactics": "Mỗi mặt chuyển một bộ quy tắc tấn công khác. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: thợ săn theo dấu.",
    "weakness": "Mặt có mắt yếu khi nhìn thấy hình phản chiếu của mình. Đây là khắc chế bằng hành động hoặc quan sát, không chỉ là một hệ nguyên tố thắng hệ khác. Có thể chuyển nó thành lựa chọn trước trận (mang vật, tìm thông tin) hoặc kỹ năng trong trận (đúng nhịp, đúng hướng, đúng vị trí). Nếu người chơi phát hiện sớm, cho phép vượt qua mà không buộc phải giết sinh vật.",
    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: mảnh mặt canh. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Bản đồ sinh cảnh thay đổi theo mùa. Khi nguồn thức ăn dịch chuyển, loài cũng rời điểm xuất hiện cố định, tránh cảm giác quái vật đứng canh một chỗ vô cớ.",
    "questHook": "Bức tượng bảo vệ lời thú nhận cất trong điện. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
