    "tactics": "Kéo giãn khoảng cách giữa hai đồng đội và cắt đường hồi cứu. Trong encounter, người chơi nên được nhìn thấy hoặc nghe dấu hiệu chuẩn bị trước khi hiệu ứng mạnh phát ra. Nhịp giao tranh đề xuất: quan sát dấu hiệu, né hoặc phá thế, tận dụng khoảng hở, sau đó thích nghi khi địa hình hoặc đội hình đổi. Vai trò thiết kế chính: đuổi bắt.",
