    "drops": "Vật liệu nhận được hoặc thu thập sau khi sinh vật tự rụng: thước đoạn không. Gợi ý công dụng là nguyên liệu chế đồ chống lại một phần năng lực vừa gặp, nhưng phẩm chất phụ thuộc phương pháp thu hoạch. Bản đồ sinh cảnh thay đổi theo mùa. Khi nguồn thức ăn dịch chuyển, loài cũng rời điểm xuất hiện cố định, tránh cảm giác quái vật đứng canh một chỗ vô cớ.",
    "questHook": "Người chơi phải quyết định bỏ lại báu vật để qua cửa. Thiết kế nhánh giải quyết gồm điều tra dấu hiệu, thương lượng hoặc di dời nếu hợp lý, đối đầu nếu cần. Kết cục nên ảnh hưởng một tuyến di cư, nghề nghiệp hoặc nguồn cung vật liệu trong vùng.",
